The strong self-consistency expression is
\begin{equation}\label{eq:self-consistency-expansion}
  \sum_{h\in\polyfunc{m}{q}{d}} \bra{\psi} H_h \ot H_h \ket{\psi}
  = \E_{u} \sum_{h \in \polyfunc{m}{q}{d}} \bra{\psi} H_h^{u} \ot H_h \ket{\psi}.
\end{equation}
Apply Lemma~\ref{lem:add-in-u} with $\mathcal O=\polyfunc{m}{q}{d}$, $M=H$, and $S_u=\{(h,h):h\in\polyfunc{m}{q}{d}\}$. This gives
\begin{equation}\label{eq:add-point-conditioning}
  \eqref{eq:self-consistency-expansion}
  \approx_{4 \sqrt{\zeta_{\mathrm{variance}}}}
  \E_{u} \sum_{h \in \polyfunc{m}{q}{d}} \bra{\psi} \bigl(A^{u}_{h(u)} \cdot H_h^{u} \cdot A^{u}_{h(u)}\bigr) \ot T_h \ket{\psi}.
\end{equation}
We next enlarge the sum from $h'=h$ to all pairs $h,h'$:
\begin{equation}\label{eq:enlarge-polynomial-sum}
  \eqref{eq:add-point-conditioning}
  \approx_{2\sqrt{\zeta_{\mathrm{variance}}} + \frac{md}{q}}
  \E_{u} \sum_{h, h' \in \polyfunc{m}{q}{d}} \bra{\psi} \bigl(A^{u}_{h(u)} \cdot H^{u}_{h'} \cdot A^{u}_{h(u)}\bigr) \ot T_h \ket{\psi}.
\end{equation}
The added off-diagonal contribution is
\begin{align}
  \eqref{eq:enlarge-polynomial-sum}-\eqref{eq:add-point-conditioning}
  &= \E_{u} \sum_{h \neq h'} \bra{\psi} \bigl(A^{u}_{h(u)} \cdot H^{u}_{h'} \cdot A^{u}_{h(u)}\bigr) \ot T_h \ket{\psi} \notag\\
  &= \E_{u} \sum_{h \neq h'} \bra{\psi} \bigl(A^{u}_{h(u)} \cdot T_{h'} \cdot A^{u}_{h(u)}\bigr) \ot T_h \ket{\psi} \cdot \bone{h(u) = h'(u)}, \label{eq:added-indicator}
\end{align}
where the second equality is~\eqref{eq:h-blt}. To estimate~\eqref{eq:added-indicator}, first replace the left copy of $A^u_{h(u)}$ by $A^v_{h(v)}$:
\begin{equation}\label{eq:swapped-u-for-v}
  \eqref{eq:added-indicator}
  \approx_{\sqrt{\zeta_{\mathrm{variance}}}}
  \E_{u,v} \sum_{h \neq h'} \bra{\psi} \bigl(A^{v}_{h(v)} \cdot T_{h'} \cdot A^{u}_{h(u)}\bigr) \ot T_h \ket{\psi} \cdot \bone{h(u) = h'(u)}.
\end{equation}
The corresponding Cauchy--Schwarz bound is
\begin{multline}
  \Big|\E_{u,v} \sum_{h \neq h'} \bra{\psi} \bigl((A^{u}_{h(u)} - A^{v}_{h(v)}) \cdot T_{h'} \cdot A^{u}_{h(u)}\bigr) \ot T_h \ket{\psi} \cdot \bone{h(u) = h'(u)}\Big|\\
  \leq
  \sqrt{\E_{u,v} \sum_{h \neq h'} \bra{\psi} \bigl((A^{u}_{h(u)} - A^{v}_{h(v)}) \cdot T_{h'} \cdot (A^{u}_{h(u)} - A^{v}_{h(v)})\bigr) \ot T_h\ket{\psi}}\\
  \cdot \sqrt{\E_{u,v} \sum_{h \neq h'} \bra{\psi} \bigl(A^{u}_{h(u)} \cdot T_{h'} \cdot A^{u}_{h(u)}\bigr) \ot T_h\ket{\psi} \cdot \bone{h(u) = h'(u)}}. \label{eq:swapped-u-for-cauchy-schwarz}
\end{multline}
The first factor is bounded by $\sqrt{\zeta_{\mathrm{variance}}}$ via Lemma~\ref{lem:global-variance-of-points}, and the second by~$1$ because $T$ and $H^u$ are submeasurements.

Repeating the same argument for the remaining copy of~$A$ yields
\begin{equation}\label{eq:replace-second-point-conditioner}
  \eqref{eq:swapped-u-for-v}
  \approx_{\sqrt{\zeta_{\mathrm{variance}}}}
  \E_{u,v} \sum_{h \neq h'} \bra{\psi} \bigl(A^{v}_{h(v)} \cdot T_{h'} \cdot A^{v}_{h(v)}\bigr) \ot T_h \ket{\psi} \cdot \bone{h(u) = h'(u)}.
\end{equation}
The same intermediate estimate gives
\begin{equation}\label{eq:swapped-indicator-total-bound}
  \E_{u,v} \sum_{h \neq h'} \bra{\psi}  \bigl(A^{v}_{h(v)} \cdot T_{h'} \cdot A^{v}_{h(v)}\bigr)\ot T_h\ket{\psi}
  \leq 1,
\end{equation}
so Schwartz--Zippel bounds the indicator average by $md/q$ and proves~\eqref{eq:enlarge-polynomial-sum}.
